import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CxcmDv9y.js";var i=JSON.parse(`{"title":"file_manager","description":"","frontmatter":{},"headers":[],"relativePath":"reference/server/http/middlewares/file_manager.md","filePath":"reference/server/http/middlewares/file_manager.md","lastUpdated":1792151331000}`),a={name:`reference/server/http/middlewares/file_manager.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="file-manager" tabindex="-1">file_manager <a class="header-anchor" href="#file-manager" aria-label="Permalink to “file_manager”">​</a></h1><p><code>file_manager</code> manages a directory through a browser UI and serves every file in it by path. Files can be anything: JSON, YAML, text, images or binaries. Text files open in an editor with syntax highlighting; other files are previewed or downloaded.</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes vesper vesper" style="--shiki-light:#FFF;--shiki-dark:#FFF;--shiki-light-bg:#101010;--shiki-dark-bg:#101010;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">server</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">  http</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">    middlewares</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">      files</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">        file_manager</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">          path</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">./data</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">          prefix_path</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">/files</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">          title</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">Shared files</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">    routers</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">      files</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">        path</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">/files/*</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">        middlewares</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">          - </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">files</span></span></code></pre></div><p>With this config:</p><table tabindex="0"><thead><tr><th>Request</th><th>Result</th></tr></thead><tbody><tr><td><code>GET /files/</code></td><td>The file manager UI.</td></tr><tr><td><code>GET /files/raw/configs/app.json</code></td><td>The file, with <code>Content-Type: application/json</code>.</td></tr><tr><td><code>GET /files/raw/configs/app.yaml</code></td><td>The file, with <code>Content-Type: application/yaml</code>.</td></tr><tr><td><code>/files/api/...</code></td><td>The JSON API the UI uses, see <a href="#api">API</a>.</td></tr></tbody></table><p>The three areas never overlap: a file named <code>api/info</code> in the directory is still served at <code>/files/raw/api/info</code>.</p><p>Raw responses support <code>ETag</code>, <code>If-None-Match</code>, <code>Last-Modified</code> and range requests. Directories are not listed on the raw path.</p><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to “Fields”">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>path</code></td><td></td><td>Directory to manage. Created when missing. Required.</td></tr><tr><td><code>prefix_path</code></td><td></td><td>Prefix stripped from the request path before lookup. Requests outside it return <code>404</code>.</td></tr><tr><td><code>read_only</code></td><td><code>false</code></td><td>Disable saving, creating, uploading, moving and deleting.</td></tr><tr><td><code>disable_ui</code></td><td><code>false</code></td><td>Serve only the raw files under <code>/raw/</code>; the UI and the API return <code>404</code>.</td></tr><tr><td><code>max_upload_size</code></td><td><code>33554432</code></td><td>Limit for a single save or upload request body, in bytes.</td></tr><tr><td><code>title</code></td><td><code>Files</code></td><td>Title shown in the UI.</td></tr><tr><td><code>cache_control</code></td><td><code>no-cache</code></td><td><code>Cache-Control</code> header for raw file responses.</td></tr></tbody></table><h2 id="ui" tabindex="-1">UI <a class="header-anchor" href="#ui" aria-label="Permalink to “UI”">​</a></h2><ul><li>Folder tree with drag and drop: drag a file or folder onto another folder to move it, or drop files and whole folders from your computer to upload them.</li><li>Previews by type: images, video and audio (played with seeking through range requests), PDF in the browser viewer, fonts with a sample text, CSV and TSV as a table, and Markdown with an edit, split or preview view.</li><li>Other binaries (archives, office documents, executables, databases) are recognised by extension and offered as a download.</li><li>Files are not downloaded in full to decide how to show them: the type comes from the extension, unknown files are sniffed from their first 8 KB, and text files over 5 MB open as a download.</li><li>Editor for text files with highlighting for about 60 languages and formats, among them JSON, YAML, TOML, INI and <code>.env</code>, XML, Markdown, HTML, CSS, SCSS, JavaScript, TypeScript, Vue, Go, Python, Rust, Java, Kotlin, C, C++, C#, Swift, PHP, Ruby, Lua, SQL, GraphQL, Protocol Buffers, Terraform, shell, PowerShell, Dockerfile, Makefile and Nginx. Files without an extension such as <code>Dockerfile</code>, <code>Makefile</code> or <code>.gitignore</code> are recognised by name. JSON is validated before saving and can be formatted.</li><li>Code is always shown dark, in the Vesper theme used by these docs, whatever the page theme.</li><li><code>Ctrl S</code> / <code>Cmd S</code> saves. Saving is guarded by the file&#39;s ETag: when someone else saved the file after you opened it, you are asked before overwriting.</li><li>Every file shows its raw URL with copy and <code>curl</code> actions.</li><li>Light and dark themes.</li></ul><h2 id="access-control" tabindex="-1">Access control <a class="header-anchor" href="#access-control" aria-label="Permalink to “Access control”">​</a></h2><p>The middleware has no authentication of its own. Put auth middlewares in front of it. Because raw files live under their own <code>/raw/</code> path, one middleware can serve both, with a separate router for public reads and a protected router for everything else:</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes vesper vesper" style="--shiki-light:#FFF;--shiki-dark:#FFF;--shiki-light-bg:#101010;--shiki-dark-bg:#101010;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">server</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">  http</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">    middlewares</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">      admin_auth</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">        basic_auth</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">          users</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">            - </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">admin:$2y$05$...</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">      files</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">        file_manager</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">          path</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">/srv/files</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">          prefix_path</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">/files</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">    routers</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">      files_raw</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">        path</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">/files/raw/*</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">        middlewares</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">          - </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">files</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">      files_admin</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">        path</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">/files/*</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">        middlewares</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">          - </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">admin_auth</span></span>
<span class="line"><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">          - </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">files</span></span></code></pre></div><p>Raw responses carry <code>Content-Security-Policy: sandbox</code> (except PDFs) and <code>X-Content-Type-Options: nosniff</code>, so an uploaded HTML or SVG file cannot run scripts against the UI&#39;s API.</p><p>All paths are resolved inside <code>path</code>; <code>..</code> segments and symlinks pointing outside the directory are rejected.</p><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to “API”">​</a></h2><p>The UI uses a small JSON API under <code>{prefix_path}/api/</code>. Write endpoints return <code>403</code> when <code>read_only</code> is set.</p><table tabindex="0"><thead><tr><th>Method</th><th>Endpoint</th><th>Description</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>info</code></td><td>UI settings: title, read-only flag, prefix and raw path.</td></tr><tr><td><code>GET</code></td><td><code>list?path=/dir</code></td><td>Directory entries, folders first.</td></tr><tr><td><code>GET</code></td><td><code>stat?path=/x</code></td><td>One entry.</td></tr><tr><td><code>GET</code></td><td><code>file?path=/x[&amp;download]</code></td><td>File content.</td></tr><tr><td><code>PUT</code></td><td><code>file?path=/x[&amp;create]</code></td><td>Write the body to the file. <code>If-Match: &lt;etag&gt;</code> rejects stale writes with <code>412</code>; <code>create</code> fails with <code>409</code> if it exists. Missing folders are created.</td></tr><tr><td><code>DELETE</code></td><td><code>file?path=/x</code></td><td>Delete a file or a folder with its contents.</td></tr><tr><td><code>POST</code></td><td><code>mkdir</code></td><td>Body <code>{&quot;path&quot;: &quot;/dir&quot;}</code>.</td></tr><tr><td><code>POST</code></td><td><code>move</code></td><td>Body <code>{&quot;from&quot;: &quot;/a&quot;, &quot;to&quot;: &quot;/b&quot;, &quot;overwrite&quot;: false}</code>. Used for rename too.</td></tr><tr><td><code>POST</code></td><td><code>upload?path=/dir[&amp;overwrite]</code></td><td>Multipart files; file names may contain folders.</td></tr></tbody></table><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes vesper vesper" style="--shiki-light:#FFF;--shiki-dark:#FFF;--shiki-light-bg:#101010;--shiki-dark-bg:#101010;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">curl</span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;"> -X</span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;"> PUT</span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;"> --data-binary</span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;"> @app.yaml</span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;"> &#39;http://localhost:8080/files/api/file?path=/configs/app.yaml&#39;</span></span></code></pre></div>`,20)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};